var hA = 0.32;          // entry height of the thick ray at lens 1 (world units)
var hB = 0.10;          // entry height of the thin ray at lens 1

/* ── diagram frame (fixed viewBox → uniform scaling at any figure size) ── */
var VW = 1000, VH = 400;
var X0 = 250, XS = 70;            // pixel of world x = 0, px per world x unit
var AY = 170, VEX = 3, YS = XS * VEX;  // axis pixel row, vertical exaggeration
