function py(w) { return AY - w * YS; }

/* ── small helpers ─────────────────────────────────────────────────────── */
function clipSeg(x1, y1, x2, y2) {
  var t0 = 0, t1 = 1, dx = x2 - x1, dy = y2 - y1;
  var p = [-dx, dx, -dy, dy], q = [x1 - XMIN, XMAX - x1, y1 - YMIN, YMAX - y1];
  for (var i = 0; i < 4; i++) {
    if (Math.abs(p[i]) < 1e-12) { if (q[i] < 0) return null; }
    else {
      var r = q[i] / p[i];
      if (p[i] < 0) { if (r > t1) return null; if (r > t0) t0 = r; }
      else { if (r < t0) return null; if (r < t1) t1 = r; }
    }
  }
  return [[x1 + dx * t0, y1 + dy * t0], [x1 + dx * t1, y1 + dy * t1]];
}

function figLabel(g, str, x, y, size, color, anchor, italic) {
