  return t;
}
function sansLabel(g, str, x, y, size, color) {
  var t = g.plain(str).font({ family: 'Helvetica, Arial, sans-serif', size: size, anchor: 'start' }).fill(color);
  t.attr({ x: x, y: y });
  return t;
}
function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}
function mathSub(g, base, sub, x, y, size, color, anchor, withHalo) {
  var t1 = figLabel(g, base, x, y, size, color, anchor, true);
  var bb;
  try { bb = t1.bbox(); } catch (e) { bb = { x2: x + size * 0.55 }; }
  var t2 = figLabel(g, sub, bb.x2 + size * 0.04, y + size * 0.26, size * 0.62, color, 'start', true);
  if (withHalo) { halo(t1); halo(t2); }
