function arcPoly(g, cx, cy, R, a0, a1, color, w) {
  var pts = [], n = 18;
  for (var i = 0; i <= n; i++) {
    var a = a0 + (a1 - a0) * i / n;
    pts.push([cx + R * Math.cos(a), cy + R * Math.sin(a)]);
