}
function biconvex(g, cx, cy, h, w, color) {
  var d = 'M ' + cx + ' ' + (cy - h) + ' Q ' + (cx + 2 * w) + ' ' + cy + ' ' + cx + ' ' + (cy + h) +
    ' Q ' + (cx - 2 * w) + ' ' + cy + ' ' + cx + ' ' + (cy - h) + ' Z';
  return g.path(d).fill('none').stroke({ color: color, width: 3, linejoin: 'round' });
}
function biconcave(g, cx, cy, h, w, inset, color) {
  var d = 'M ' + (cx - w) + ' ' + (cy - h) + ' Q ' + (cx - w + 2 * inset) + ' ' + cy + ' ' + (cx - w) + ' ' + (cy + h) +
    ' L ' + (cx + w) + ' ' + (cy + h) + ' Q ' + (cx + w - 2 * inset) + ' ' + cy + ' ' + (cx + w) + ' ' + (cy - h) + ' Z';
  return g.path(d).fill('none').stroke({ color: color, width: 3, linejoin: 'round' });
}
function bracket(g, x1, x2, y, tick, color) {
  var gg = g.group();
  gg.line(x1, y, x2, y).stroke({ color: color, width: 2.2 });
  gg.line(x1, y - tick, x1, y + tick).stroke({ color: color, width: 2.2 });
