function rayData(h, t, f1, f2, sep) {
  var m1 = -t - h / f1;          // slope after the convex objective
  var y2 = h + m1 * sep;         // height at the eyepiece
  var m2 = m1 + y2 / f2;         // slope after the concave eyepiece (f = -f2)
  return { h: h, m1: m1, y2: y2, m2: m2 };
