// @FIGURE_CODE_BEGIN
/* ── state ─────────────────────────────────────────────────────────────── */
var S = { f1: 6, f2: 2, di: 1.5, lock: true, off: 0 };
var hA = 0.32;          // entry height of the thick ray at lens 1 (world units)
var hB = 0.12;          // entry height of the thin ray at lens 1

/* ── diagram frame (fixed viewBox → uniform scaling at any figure size) ── */
var VW = 1000, VH = 400;
var X0 = 250, XS = 76;                 // pixel of world x = 0, px per world unit
var AY = 160, VEX = 3, YS = XS * VEX;  // axis pixel row, vertical exaggeration
var XMIN = 72, XMAX = 994, YMIN = 12, YMAX = 306; // ray clipping window
var LH1 = 124, LH2 = Math.round(LH1 * 0.58);      // lens half-heights (FIXED)

var C = { ray: '#c77fe0', rayD: '#b160d6', blue: '#0d0dd9', lab: '#0000ff', blk: '#000000' };

var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, VW, VH);
var root = figDraw.group();

function px(w) { return X0 + w * XS; }
function py(w) { return AY - w * YS; }

/* ── small helpers ─────────────────────────────────────────────────────── */
function clipSeg(x1, y1, x2, y2) {
  var t0 = 0, t1 = 1, dx = x2 - x1, dy = y2 - y1;
  var p = [-dx, dx, -dy, dy], q = [x1 - XMIN, XMAX - x1, y1 - YMIN, YMAX - y1];
  for (var i = 0; i < 4; i++) {
    if (Math.abs(p[i]) < 1e-12) { if (q[i] < 0) return null; }
    else {
      var r = q[i] / p[i];
      if (p[i] < 0) { if (r > t1) return null; if (r > t0) t0 = r; }
      else { if (r < t0) return null; if (r < t1) t1 = r; }
    }
  }
  return [[x1 + dx * t0, y1 + dy * t0], [x1 + dx * t1, y1 + dy * t1]];
}
function figLabel(g, str, x, y, size, color, anchor, italic) {
  var t = g.plain(str).font({
    family: 'Georgia, "Times New Roman", Times, serif', size: size, anchor: anchor || 'start'
  }).fill(color);
  if (italic) t.font({ style: 'italic' });
  t.attr({ x: x, y: y });
  return t;
}
function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}
function mathSub(g, base, sub, x, y, size, color, anchor, withHalo) {
  var t1 = figLabel(g, base, x, y, size, color, anchor, true);
  var bb;
  try { bb = t1.bbox(); } catch (e) { bb = { x2: x + size * 0.55 }; }
  var t2 = figLabel(g, sub, bb.x2 + size * 0.04, y + size * 0.26, size * 0.62, color, 'start', true);
  if (withHalo) { halo(t1); halo(t2); }
  return [t1, t2];
}
function arrowHead(g, x, y, dx, dy, size, color) {
  var L = Math.sqrt(dx * dx + dy * dy) || 1, ux = dx / L, uy = dy / L, nx = -uy, ny = ux;
  var pts = [[x, y],
  [x - ux * size + nx * size * 0.42, y - uy * size + ny * size * 0.42],
  [x - ux * size - nx * size * 0.42, y - uy * size - ny * size * 0.42]];
  return g.polygon(pts.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' ')).fill(color);
}
function arcPoly(g, cx, cy, R, a0, a1, color, w) {
  var pts = [], n = 18;
  for (var i = 0; i <= n; i++) {
    var a = a0 + (a1 - a0) * i / n;
    pts.push([cx + R * Math.cos(a), cy + R * Math.sin(a)]);
  }
  g.polyline(pts.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' '))
    .fill('none').stroke({ color: color, width: w || 1.8, linecap: 'round' });
  return pts;
}
function biconvex(g, cx, cy, h, w, color) {
  var d = 'M ' + cx + ' ' + (cy - h) + ' Q ' + (cx + 2 * w) + ' ' + cy + ' ' + cx + ' ' + (cy + h) +
    ' Q ' + (cx - 2 * w) + ' ' + cy + ' ' + cx + ' ' + (cy - h) + ' Z';
  return g.path(d).fill('none').stroke({ color: color, width: 3, linejoin: 'round' });
}
function biconcave(g, cx, cy, h, w, inset, color) {
  var d = 'M ' + (cx - w) + ' ' + (cy - h) + ' Q ' + (cx - w + 2 * inset) + ' ' + cy + ' ' + (cx - w) + ' ' + (cy + h) +
    ' L ' + (cx + w) + ' ' + (cy + h) + ' Q ' + (cx + w - 2 * inset) + ' ' + cy + ' ' + (cx + w) + ' ' + (cy - h) + ' Z';
  return g.path(d).fill('none').stroke({ color: color, width: 3, linejoin: 'round' });
}
function bracket(g, x1, x2, y, tick, color) {
  var gg = g.group();
  gg.line(x1, y, x2, y).stroke({ color: color, width: 2.2 });
  gg.line(x1, y - tick, x1, y + tick).stroke({ color: color, width: 2.2 });
  gg.line(x2, y - tick, x2, y + tick).stroke({ color: color, width: 2.2 });
  return gg;
}
function hov(el, tip, ptitle, pbody) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (ptitle) el.on('click', function () { showPopup(ptitle, pbody); });
  return el;
}

/* ── ray transfer through the two thin lenses ──────────────────────────── */
function rayData(h, t, f1, f2, sep) {
  var m1 = -t - h / f1;          // slope after the convex objective
  var y2 = h + m1 * sep;         // height at the eyepiece
  var m2 = m1 + y2 / f2;         // slope after the concave eyepiece (f = −f₂)
  return { h: h, m1: m1, y2: y2, m2: m2 };
}

/* ── main render ───────────────────────────────────────────────────────── */
function drawAll() {
  root.clear();
  var t = Math.tan(S.di * Math.PI / 180);
  var f1 = S.f1;
  var f2 = Math.min(S.f2, f1 - 0.4);
  var afocSep = f1 - f2;
  var sep = afocSep + (S.lock ? 0 : S.off);
  sep = Math.max(0.6, Math.min(f1 + 1.6, sep));
  var afoc = Math.abs(sep - afocSep) < 1e-9;
  var d = t * f1;                                  // focal offset (below axis if t > 0)
  var rA = rayData(hA, t, f1, f2, sep);
  var rB = rayData(hB, t, f1, f2, sep);

  /* optical axis */
  hov(root.line(18, AY, VW - 6, AY).stroke({ color: C.blue, width: 1.4 }),
    'optical axis', 'Optical axis',
    'The common axis of the two lenses. Both δᵢ and δₒ are measured from this line; the lower input ray uses the axis itself as its reference line.');

  /* blue reference line at the thick ray entry height */
  root.line(XMIN, py(hA), px(0), py(hA)).stroke({ color: C.blue, width: 1.2 });

  /* brackets f₁ and f₂ */
  var b1 = bracket(root, px(0), px(f1), 372, 9, C.blk);
  mathSub(root, 'f', '1', (px(0) + px(f1)) / 2 - 6, 358, 24, C.blk, 'middle');
  hov(b1, 'f₁ = ' + f1.toFixed(1) + ' — lens 1 to the focal plane', 'Objective focal length f₁',
    'Parallel light entering the convex objective is focused in its focal plane, one f₁ to the right of the lens. Lengthening f₁ pushes that plane further right and raises the magnification f₁/f₂.');
  var b2 = bracket(root, px(sep), px(sep + f2), 330, 9, C.blk);
  mathSub(root, 'f', '2', (px(sep) + px(sep + f2)) / 2 - 6, 316, 24, C.blk, 'middle');
  hov(b2, 'f₂ = ' + f2.toFixed(1) + (afoc ? ' — ends exactly on the focal plane' : ' — no longer ends on the focal plane'),
    'Eyepiece focal length f₂',
    'The concave eyepiece has its own focal plane one f₂ away. Only when that plane coincides with the objective\'s focal plane (the two bracket ends line up) does the light leave as a parallel bundle.');

  /* lenses */
  var L1 = biconvex(root, px(0), AY, LH1, 9, C.blk);
  hov(L1, 'lens 1 — convex objective, f₁ = ' + f1.toFixed(1), 'Lens 1 — objective (convex, f₁)',
    'Every parallel bundle tilted by δᵢ is brought to one point in the objective focal plane, a height d = f₁·tan δᵢ off the axis. A bigger input tilt simply slides that point along the focal plane.');
  var L2 = biconcave(root, px(sep), AY, LH2, 11, 6, C.blk);
  hov(L2, 'lens 2 — concave eyepiece, f₂ = ' + f2.toFixed(1), 'Lens 2 — eyepiece (concave, f₂)',
    'The diverging eyepiece sits one f₂ before the objective\'s focal plane, so the converging cone is straightened back into a parallel bundle, now tilted by δₒ with tan δₒ = d/f₂. Move it and the exit bundle stops being parallel.');

  /* dashed continuation of the thin ray towards the shared focal point */
  var dsh = clipSeg(px(sep), py(rB.y2), px(f1), py(-d));
  if (dsh) {
    root.line(dsh[0][0], dsh[0][1], dsh[1][0], dsh[1][1])
      .stroke({ color: C.rayD, width: 2, dasharray: '7,5', linecap: 'round' });
  }

  /* rays */
  function drawRay(r, thick, name) {
    var w = thick ? 6.5 : 1.9;
    var g = root.group();
    var P0 = [px(0), py(r.h)], P2 = [px(sep), py(r.y2)];
    // thick ray terminates at the shared focal plane, as in the source figure
    var xEnd = thick ? Math.max(f1, sep + 0.8) : ((XMAX - X0) / XS + 1);
    var segs = [
      clipSeg(px(-9), py(r.h + 9 * t), P0[0], P0[1]),
      clipSeg(P0[0], P0[1], P2[0], P2[1]),
      clipSeg(P2[0], P2[1], px(xEnd), py(r.y2 + r.m2 * (xEnd - sep)))
    ];
    for (var i = 0; i < segs.length; i++) {
      if (!segs[i]) continue;
      g.line(segs[i][0][0], segs[i][0][1], segs[i][1][0], segs[i][1][1])
        .stroke({ color: C.ray, width: w, linecap: 'round' });
    }
    hov(g, name + ' — in at δᵢ = ' + S.di.toFixed(1) + '°, out at ' +
      (Math.atan(-r.m2) * 180 / Math.PI).toFixed(2) + '°',
      name, 'Both input rays are parallel (same δᵢ). The objective aims them at one common focal point; the eyepiece re-collimates them, so they leave parallel again but steeper — that steepening is the angular magnification.');
    return g;
  }
  drawRay(rB, false, 'Ray B (thin)');
  drawRay(rA, true, 'Ray A (thick)');

  /* where the exit rays cross when the telescope is not afocal */
  if (!afoc && Math.abs(rA.m2 - rB.m2) > 1e-6) {
    var xc = sep + (rB.y2 - rA.y2) / (rA.m2 - rB.m2);
    var yc = rA.y2 + rA.m2 * (xc - sep);
    var pxc = px(xc), pyc = py(yc);
    if (pxc > XMIN && pxc < XMAX && pyc > YMIN && pyc < YMAX) {
      hov(root.circle(15).center(pxc, pyc).fill('none').stroke({ color: '#e06a00', width: 2.2 }),
        'exit rays cross here — the bundle is not parallel', 'Not afocal',
        'With the eyepiece off the afocal spacing the exit rays converge (or diverge) and meet at a finite distance, so a distant object no longer appears at infinity to the relaxed eye.');
    }
  }

  /* shared focal point, axis dot and the d arrow */
  var fx = px(f1), fy = py(-d);
  var dotG = root.group();
  dotG.circle(11).center(fx, AY).fill(C.lab);
  dotG.circle(15).center(fx, fy).fill(C.ray).stroke({ color: C.rayD, width: 1.5 });
  if (Math.abs(fy - AY) > 12) {
    var sgn = (fy > AY) ? 1 : -1;
    dotG.line(fx, AY + sgn * 6, fx, fy - sgn * 8).stroke({ color: C.blk, width: 2 });
    arrowHead(dotG, fx, fy - sgn * 7, 0, sgn, 10, C.blk);
    halo(figLabel(root, 'd', fx + 11, (AY + fy) / 2 + sgn * 4 + 7, 23, C.blk, 'start', false));
  }
  hov(dotG, 'shared focal point — d = ' + Math.abs(d).toFixed(3),
    'The shared focal plane',
    'Both lenses focus on this one plane, so the same off-axis height d serves both: d = f₁·tan δᵢ for the objective and d = f₂·tan δₒ for the eyepiece. Eliminating d gives δₒ/δᵢ = f₁/f₂ — the angular magnification is just the ratio of focal lengths.');

  /* δᵢ hooks and labels at the far left */
  if (Math.abs(t) > 0.0015) {
    var xh = 95, wxh = (xh - X0) / XS;
    function hook(refY, rayY, labY) {
      var mid = (refY + rayY) / 2;
      root.path('M ' + xh + ' ' + refY + ' Q ' + (xh - 14) + ' ' + mid + ' ' + xh + ' ' + rayY)
        .fill('none').stroke({ color: C.blk, width: 1.8 });
      arrowHead(root, xh, rayY, -1, -t * VEX, 9, C.blk);
      mathSub(root, 'δ', 'i', 26, labY, 24, C.blk, 'start', true);
    }
    var rayAy = py(hA - t * wxh), rayBy = py(hB - t * wxh);
    hook(py(hA), rayAy, (py(hA) + rayAy) / 2 + 7);
    hook(AY, rayBy, (AY + rayBy) / 2 + 7);
  }

  /* δₒ annotation at the far right margin */
  if (Math.abs(t) > 0.0015) {
    var ax = 900, R = 34;
    var a1 = Math.atan(-rA.m2 * VEX);
    var pts = arcPoly(root, ax, AY, R, 0, a1, C.blk, 1.8);
    var pe = pts[pts.length - 1], pp = pts[pts.length - 2];
    arrowHead(root, pe[0], pe[1], pe[0] - pp[0], pe[1] - pp[1], 10, C.blk);
    var ly = AY + R * Math.sin(a1) + (a1 >= 0 ? 20 : -8);
    mathSub(root, 'δ', 'o', ax + R + 8, ly, 24, C.blk, 'start', true);
  }

  /* lens name labels */
  halo(figLabel(root, 'lens 1', px(0), AY - LH1 - 12, 22, C.lab, 'middle', false));
  halo(figLabel(root, 'lens 2', px(sep), AY - LH2 - 12, 22, C.lab, 'middle', false));

  /* numeric readout lives in the HTML control column (never over the figure) */
  var doDeg = Math.atan(-rA.m2) * 180 / Math.PI;
  updateReadout(f1, f2, sep, afoc, doDeg, d, f2 * Math.abs(rA.m2));
}

/* ── readout (HTML panel) ──────────────────────────────────────────────── */
function updateReadout(f1, f2, sep, afoc, doDeg, d, f2tan) {
  function $(id) { return document.getElementById(id); }
  $('roF').textContent = 'f₁ = ' + f1.toFixed(1) + '  ·  f₂ = ' + f2.toFixed(1) +
    '  ·  separation = ' + sep.toFixed(2);
  $('roAng').textContent = 'δᵢ = ' + S.di.toFixed(1) + '°  ·  δₒ = ' + doDeg.toFixed(2) + '°';
  if (afoc) {
    var m = (Math.abs(S.di) > 1e-6) ? Math.abs(doDeg / S.di) : (f1 / f2);
    $('roM').textContent = 'M = δₒ/δᵢ = ' + m.toFixed(2) + ' = f₁/f₂ = ' + (f1 / f2).toFixed(2);
    $('roD').textContent = 'd = f₁·tanδᵢ = f₂·tanδₒ = ' + Math.abs(d).toFixed(3);
    $('roStatus').textContent = '✓ afocal — exit bundle is parallel';
    $('roStatus').style.color = '#1b7a2f';
  } else {
    $('roM').textContent = 'Exit rays are not parallel, so there is no single δₒ — M is undefined (δₒ above is the thick ray alone).';
    $('roD').textContent = 'f₁·tanδᵢ = ' + Math.abs(d).toFixed(3) +
      '   but   f₂·tanδₒ = ' + f2tan.toFixed(3) + '  → no longer equal';
    $('roStatus').textContent = '✗ not afocal — eyepiece shifted by Δ = ' + (sep - (f1 - f2)).toFixed(2);
    $('roStatus').style.color = '#c23b00';
  }
}

/* ── control handlers ──────────────────────────────────────────────────── */
function clampF2() {
  var lim = Math.round((S.f1 - 0.4) * 10) / 10;
  if (S.f2 > lim) S.f2 = lim;
  if (S.f2 < 0.5) S.f2 = 0.5;
}
function syncUI() {
  document.getElementById('focalLength1Input').value = S.f1;
  document.getElementById('focalLength1Val').value = S.f1.toFixed(1);
  document.getElementById('focalLength2Input').value = S.f2;
  document.getElementById('focalLength2Val').value = S.f2.toFixed(1);
  document.getElementById('inputAngleInput').value = S.di;
  document.getElementById('inputAngleVal').value = S.di.toFixed(1);
  document.getElementById('afocalLockInput').checked = S.lock;
  document.getElementById('lens2OffsetInput').value = S.off;
  document.getElementById('lens2OffsetInput').disabled = S.lock;
  document.getElementById('lens2OffsetVal').value = S.off.toFixed(2);
}
function update_focalLength1(v) { S.f1 = v; clampF2(); syncUI(); drawAll(); }
function update_focalLength2(v) { S.f2 = v; clampF2(); syncUI(); drawAll(); }
function update_inputAngle(v) { S.di = v; drawAll(); }
function toggle_afocalLock(on) { S.lock = on; syncUI(); drawAll(); }
function update_lens2Offset(v) { S.off = v; if (!S.lock) drawAll(); }

/* ── demo step player ──────────────────────────────────────────────────── */
var STEPS = [
  {
    title: 'The afocal baseline',
    narration: 'Two parallel rays arrive tilted by δᵢ. The convex objective aims them at a point one f₁ away, and the concave eyepiece — placed one f₂ short of that point — straightens them into a parallel bundle again, now tilted by the larger angle δₒ.',
    state: { focalLength1: 6, focalLength2: 2, inputAngle: 1.5, afocalLock: true, lens2Offset: 0 }
  },
  {
    title: 'Angle in, angle out',
    narration: 'Sweep the input tilt. The focal point slides along the focal plane (d = f₁·tanδᵢ) and the exit angle follows in lockstep — but the ratio δₒ/δᵢ never budges.',
    state: { focalLength1: 6, focalLength2: 2, inputAngle: -2.5, afocalLock: true, lens2Offset: 0 }
  },
  {
    title: 'Magnification is a ratio',
    narration: 'Shorten the eyepiece focal length. The lens separation shrinks to stay afocal, the exit rays fan out much more steeply, and the readout climbs to M = f₁/f₂.',
    state: { focalLength1: 7, focalLength2: 1, inputAngle: 1.5, afocalLock: true, lens2Offset: 0 }
  },
  {
    title: 'Break the afocal condition',
    narration: 'Unlock and slide the eyepiece away from f₁ − f₂. The f₂ bracket no longer reaches the focal plane, the exit bundle stops being parallel (orange crossing), and f₁·tanδᵢ and f₂·tanδₒ are no longer equal.',
    state: { focalLength1: 6, focalLength2: 2, inputAngle: 1.5, afocalLock: false, lens2Offset: 0.8 }
  },
  {
    title: 'Restore alignment',
    narration: 'Return the eyepiece to the afocal spacing and the bundle snaps back to parallel — this is the focusing adjustment on a real Galilean telescope.',
    state: { focalLength1: 6, focalLength2: 2, inputAngle: 1.5, afocalLock: true, lens2Offset: 0 }
  }
];
var curStep = 0;
function setStep(i) {
  curStep = (i + STEPS.length) % STEPS.length;
  var st = STEPS[curStep].state;
  S.f1 = st.focalLength1; S.f2 = st.focalLength2; S.di = st.inputAngle;
  S.lock = st.afocalLock; S.off = st.lens2Offset;
  clampF2();
  document.getElementById('stepTitle').textContent = 'Step ' + (curStep + 1) + ' · ' + STEPS[curStep].title;
  document.getElementById('demoNarration').textContent = STEPS[curStep].narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + STEPS.length;
  syncUI();
  drawAll();
}
function nextStep() { setStep(curStep + 1); }
function prevStep() { setStep(curStep - 1); }

setStep(0);
